def solve_normal(input_str):
    events, m = parse_input(input_str)

    # Create segments between type-1 events
    # Each segment contains set of friends who visit during that segment
    segments = []
    current_segment = defaultdict(set)
    segment_events = []  # all events in current segment with their friend indices

    # Track which friends visit in which segment by friend_id
    # Segment is identified by index
    friend_segment_info = defaultdict(lambda: defaultdict(set))  # friend -> list of segments

    friend_counter = {}  # map friend name to integer index
    friend_list = []

    friend_segment_access = defaultdict(list)  # friend -> list of (segment_index, viewed)

    segment_idx = 0
    segment_id = -1

    for evt_type, friend_name in events:
        if evt_type == '1':
            # Start a new segment, save current
            if segment_idx > 0 and segment_id >= 0:
                for f in current_segment:
                    friend_segment_access[f].append((segment_id, True))
                segments.append((current_segment, segment_id))
            current_segment = defaultdict(set)
            segment_id = -1
            segment_idx += 1
        else:
            # Friend visits
            friend_name = friend_name
            # Track segment for this friend
            friend_segment_info[friend_name][segment_id].add('1')
            current_segment[friend_name] = True

    # After loop, save last segment
    for f in current_segment:
        friend_segment_access[f].append((segment_id, True))
    if segment_id >= 0:
        segments.append((current_segment, segment_id))

    # Now we have segments
    # Each segment has a set of friends who visited

    segments_data = []
    for seg_id, friend_set in segments:
        segments_data.append(set(friend_set.keys()))

    if not segments_data:
        return 0

    # Build constraints: for each friend, which segments they appear in
    # Friend i must have their handle chosen in ALL segments where they appear
    # In any segment, we can choose at most one friend's handle

    n_segments = len(segments_data)

    # For each segment, get the set of friends that appear in it
    segment_friends = list(segments_data)

    # For each friend, get segments where they appear
    friend_segments = defaultdict(list)
    for seg_idx, seg in enumerate(segments_data):
        friend_segments[seg].append(seg_idx)

    # Build incompatibility between friends:
    # Friend A and Friend B are incompatible if they both appear in the same segment
    # In that segment, we can only pick ONE of them

    # This becomes a maximum independent set problem on the incompatibility graph
    # Vertices = friends, edge between two friends if they're incompatible

    friends_in_segments = defaultdict(set)
    for seg_idx, seg in enumerate(segments_data):
        for friend in seg:
            friends_in_segments[friend].add(seg_idx)

    if not friends_in_segments:
        return 0

    present_friends = set(friends_in_segments.keys())

    if len(present_friends) <= 1:
        return min(1, len(present_friends))

    # Build adjacency list
    adj = defaultdict(set)
    for f1 in present_friends:
        for f2 in present_friends:
            if f1 < f2:
                # Intersect their segment sets
                segs1 = friends_in_segments[f1]
                segs2 = friends_in_segments[f2]
                if segs1.intersection(segs2):
                    adj[f1].add(f2)
                    adj[f2].add(f1)

    # Maximum independent set on this graph
    # Use bitmask DP or branch and bound
    n = len(present_friends)
    present_list = list(present_friends)
    mapping = {f: i for i, f in enumerate(present_list)}
    inv_mapping = {i: f for i, f in enumerate(present_list)}

    m_size = n
    if m_size == 0:
        return 0
    if m_size == 1:
        return 1

    # Convert adjacency to bitmask
    adj_mask = [0] * m_size
    for i, f in enumerate(present_list):
        mask = 0
        for neighbor in adj[f]:
            if neighbor in mapping:
                j = mapping[neighbor]
                mask |= (1 << j)
        adj_mask[i] = mask

    # Maximum independent set via branch and bound
    max_taken = 0

    def dfs(current_mask, count):
        nonlocal max_taken
        max_taken = max(max_taken, count)

        # Find lowest bit
        lowest = (current_mask & -current_mask).bit_length() - 1
        if lowest >= m_size:
            return

        # Either take node 'lowest' or don't take it
        # Don't take
        dfs(current_mask, count)
        # Take
        take_mask = adj_mask[lowest] & current_mask
        new_count = count + 1
        dfs(current_mask & ~take_mask, new_count)

    # Better: use branch and bound with pruning
    order = sorted(range(m_size), key=lambda i: bin(adj_mask[i]).count('1'), reverse=True)

    # Pruned DFS
    def dfs_with_limit(mask, count, pos):
        nonlocal max_taken
        max_taken = max(max_taken, count)

        if pos < len(order):
            idx = order[pos]
            neighbors = adj_mask[idx] & mask
            if not neighbors:
                # idx has no neighbors in remaining mask, take it
                dfs_with_limit(mask & ~neighbors, count + 1, pos + 1)
                # Also can leave it
                dfs_with_limit(mask, count, pos + 1)
            else:
                # idx has neighbors, we can either take or not
                # If we take idx, remove it and all its neighbors
                dfs_with_limit(mask & ~adj_mask[idx], count + 1, pos + 1)
                # If not, we skip handling idx specifically
                dfs_with_limit(mask, count, pos + 1)
        else:
            max_taken = max(max_taken, count)

    dfs_with_limit(0, 0, 0)

    return max_taken

