def is_prime(n):
    """Check if n is prime"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def can_be_sum_of_two_squares(n):
    """Check if n can be written as a² + b² with a, b > 0"""
    if n < 2:
        return False
    if n == 2:
        return True  # 2 = 1² + 1²

    # For prime numbers:
    # - 2 can be written as sum of two squares (1² + 1²)
    # - Primes p ≡ 1 (mod 4) can be written as sum of two squares (Fermat's theorem)
    # - Primes p ≡ 3 (mod 4) CANNOT be written as sum of two squares

    # For composite numbers, we need to check all factorizations
    # But since we're checking primes only, we use the simpler rule

    if is_prime(n):
        return n == 2 or n % 4 == 1

    # For composite numbers (not needed since we check primes only above, but let's be thorough)
    # A number can be written as sum of two squares if all prime factors ≡ 3 (mod 4) have even exponents
    temp = n
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            if d % 4 == 3 and count % 2 == 1:
                return False
        d += 1
    if temp > 1 and temp % 4 == 3:
        return False
    return True

