def solution(input_string):
    from collections import deque

    input_string = input_string.replace('\r\n', '\n').replace('\r', '\n')
    lines = input_string.strip('\n').split('\n')

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    roads = []
    graph = [[] for _ in range(n + 1)]

    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        roads.append((x, y, w, i + 1))
        graph[x].append((y, i))
        graph[y].append((x, i))

    def bfs_check(removed_edges):
        if s == t:
            return True
        if not removed_edges:
            return t in [v for u, v in graph[s]]

        visited = {s}
        queue = deque([s])

        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v, edge_id in graph[u]:
                if edge_id not in removed_edges and v not in visited:
                    visited.add(v)
                    queue.append(v)

        return t in visited

    # Check 0 edges
    if not bfs_check(set()):
        return '0\n0\n'

