        x, y, w, idx = roads[i]
        if not bfs_check({idx}):
            if w < best_c1:
                best_c1 = w
                edge1 = idx

    if best_c1 != float('inf'):
        return f'{best_c1}\n1\n{edge1}'

    # Check 2 edges - efficient approach
    # Find edges on s-t path using first-touch node concepts
    visited_from_s = {s}
    queue = deque([s])

    first_touch = {}

    while queue:
        u = queue.popleft()
        for v, edge_id in graph[u]:
            if v not in visited_from_s:
                first_touch[v] = u
                visited_from_s.add(v)
                queue.append(v)

    visited_to_t = {t}
    queue = deque([t])

    while queue:
        u = queue.popleft()
        for v, edge_id in graph[u]:
            if v not in visited_to_t:
                visited_to_t.add(v)
                queue.append(v)

    path_edges = set()
    for x, y, w, idx in roads:
        if (x in visited_from_s and y in visited_to_t) or (y in visited_from_s and x in visited_to_t):
