def solution(input_str):
    import sys
    sys.setrecursionlimit(1000000)

    lines = input_str.strip().split('\n')
    if not lines:
        return 'YES\n' + ''.join(['0'] * 0)

    n, m = map(int, lines[0].split())

    # Read clauses
    clauses = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        clauses.append(parts[1:])

    # Build implication graph: 2m nodes
    # Node i (0 <= i < m): x_{i+1} is true
    # Node i + m (0 <= i < m): x_{i+1} is false

    def get_node_for_literal(literal):
        """Get node index for a literal"""
        var = abs(literal) - 1  # 0-indexed
        return var if literal > 0 else var + m

    def get_negate(literal):
        """Get negated literal"""
        return -literal

    graph = [[] for _ in range(2 * m)]
    rev_graph = [[] for _ in range(2 * m)]

    for clause in clauses:
        for i in range(len(clause)):
            for j in range(i + 1, len(clause)):
                l1, l2 = clause[i], clause[j]

                # ¬l1 → l2
                not_l1 = get_negate(l1)
                node_not_l1 = get_node_for_literal(not_l1)
                node_l2 = get_node_for_literal(l2)
                if node_not_l1 != node_l2:
                    graph[node_not_l1].append(node_l2)
                    rev_graph[node_l2].append(node_not_l1)

                # ¬l2 → l1
                not_l2 = get_negate(l2)
                node_not_l2 = get_node_for_literal(not_l2)
                node_l1 = get_node_for_literal(l1)
                if node_not_l2 != node_l1:
                    graph[node_not_l2].append(node_l1)
                    rev_graph[node_l1].append(node_not_l2)

    # Kosaraju's algorithm for SCCs
    visited = [False] * (2 * m)
    order = []

    def dfs1(u):
        stack = [(u, 0)]
        while stack:
            node, state = stack.pop()
            if state == 0:
                if visited[node]:
                    continue
                visited[node] = True
                stack.append((node, 1))
                for v in graph[node]:
                    if not visited[v]:
                        stack.append((v, 0))
            else:
                order.append(node)

    for i in range(2 * m):
        if not visited[i]:
            dfs1(i)

    visited = [False] * (2 * m)
    scc_id = [-1] * (2 * m)
    scc_count = 0

    def dfs2(u, scc_num):
        stack = [u]
        while stack:
            node = stack.pop()
            if scc_id[node] != -1:
                continue
            scc_id[node] = scc_num
            for v in rev_graph[node]:
