def solution(input_str):
    """
    Find the minimum weight shortest path tree from the given start vertex.

    Args:
        input_str: String containing the input in format:
            n m
            u1 v1 w1
            ...
            um vm wm
            start_vertex

    Returns:
        String with total weight and edge indices
    """
    # Parse input
    tokens = input_str.replace('\n', ' ').split()
    idx = 0

    n = int(tokens[idx]); idx += 1
    m = int(tokens[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        u = int(tokens[idx]); idx += 1
        v = int(tokens[idx]); idx += 1
        w = int(tokens[idx]); idx += 1
        adj[u].append((v, w, i))
        adj[v].append((u, w, i))

    start_vertex = int(tokens[idx])

    # Dijkstra's algorithm to find shortest distances
    dist = [float('inf')] * (n + 1)
    dist[start_vertex] = 0
    pq = [(0, start_vertex)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w, _ in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # For each vertex, select the minimum weight edge from valid parents
    min_total_weight = 0
    selected_edge_indices = []

    for v in range(1, n + 1):
        if v == start_vertex:
            continue

        # A parent u is valid if dist[u] + u->v_weight == dist[v]
        # Among all valid parents, pick the minimum weight edge
        best_edge_index = -1
        best_weight = float('inf')

        for u, w, edge_index in adj[v]:
            # Check if this edge is on a shortest path
            if dist[u] + w == dist[v] and w < best_weight:
                best_weight = w
                best_edge_index = edge_index

        if best_edge_index != -1:
            min_total_weight += best_weight
            selected_edge_indices.append(best_edge_index)

    # Format output (matching expected format with trailing spaces)
    indices_str = ' '.join(map(str, selected_edge_indices)) + ' ' if selected_edge_indices else ''
    return f"{min_total_weight}\n{indices_str}"

