def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]

    # Find all connected components of free spaces
    visited = [[False] * m for _ in range(n)]
    components = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                component = []
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    r, c = stack.pop()
                    component.append((r, c))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                components.append(component)

    # For each component, calculate its bounding box and remove walls within it
    # This makes each component a perfect rectangle
    walls_to_remove = set()

    for comp in components:
        min_r, max_r, min_c, max_c = float('inf'), float('inf'), float('inf'), float('inf')
        for r, c in comp:
            min_r = min(min_r, r)
            max_r = max(max_r, r)
            min_c = min(min_c, c)
            max_c = max(max_c, c)

        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if (r, c) not in comp and grid[r][c] == '*':
                    walls_to_remove.add((r, c))

    # Apply wall removals
    for r, c in walls_to_remove:
        grid[r][c] = '.'

    # Return the modified grid
    return '\n'.join(''.join(row) for row in grid)

