def BFS_path(grid, swap_ud, swap_lr):
    """BFS to find path given specific swap configuration"""
    n = len(grid)
    m = len(grid[0])
    start = (0, 0)

    # Find finish
    finish = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'F':
                finish = (i, j)
                break

    # Direction mapping
    moves = {
        'U': (0, -1),
        'D': (0, 1), 
        'L': (-1, 0),
        'R': (1, 0)
    }

    # Apply swaps
    def actual_dir(move):
        if move == 'U':
            return (0, -1) if not swap_ud else (0, 1)
        if move == 'D':
            return (0, 1) if not swap_ud else (0, -1)
        if move == 'L':
            return (-1, 0) if not swap_lr else (1, 0)
        if move == 'R':
            return (1, 0) if not swap_lr else (-1, 0)
        return (0, 0)

    from collections import deque
    queue = deque([(start, [])])
    visited = {start}

    while queue:
        pos, path = queue.popleft()

        if pos == finish:
            return path

        for move in ['U', 'D', 'L', 'R']:
            di, dj = actual_dir(move)
            ni, nj = pos[0] + di, pos[1] + dj

            if 0 <= ni < n and 0 <= nj < m:
                if grid[ni][nj] == '*':
                    continue
                if (ni, nj) not in visited:
                    visited.add((ni, nj))
                    queue.append(((ni, nj), path + [move]))

    return []


