def can_buy(n, k, offers, day):
    if day == 0:
        return all(x == 0 for x in k)

    type_last_sale = {}
    for d_j, t_j in offers:
        if d_j <= day:
            type_last_sale[t_j] = max(type_last_sale.get(t_j, 0), d_j)

    from collections import defaultdict
    schedule = defaultdict(int)
    for t, sday in type_last_sale.items():
        schedule[sday] += k[t-1]

    cnt = sum(f := schedule[d] for d in sorted(schedule, reverse=True))
    remaining = sum(k[i-1] for i in range(1, n+1)) - cnt

    total_spent = 2 * cnt + remaining
    return total_spent <= day

