        elif s == 'B':
            B_edges.append((p1, p2))
        elif s == 'R':
            R_edges.append((p1, p2))

    # Check for cycles using topological sort
    def check_cycle(ncount, edges):
        adj = defaultdict(list)
        for n1, n2 in edges:
            adj[n1].append(n2)

        # Kahn's algorithm
        in_degree = [0] * ncount
        for i in range(ncount):
            for nb in adj[i]:
                in_degree[nb] += 1

        queue = deque([i for i in range(ncount) if in_degree[i] == 0])
        order = []

        while queue:
            node = queue.popleft()
            order.append(node)
            for nb in adj[node]:
                in_degree[nb] -= 1
                if in_degree[nb] == 0:
                    queue.append(nb)

        return len(order) == ncount, order

