        # Binary split for efficiency
        mid = (l + r) // 2
        v1, len1 = range_nodigits(l, mid, d)
        v2, len2 = range_nodigits(mid + 1, r, d)

        if len1 == 0 or len2 == 0:
            comp_len = len2 if len1 == 0 else len1
            return (v2 if len1 == 0 else v1, comp_len)

        val = (v1 * pow(10, len2, mod) + v2) % mod
        ln = len1 + len2
        return (val, ln)

    def concat(a, b):
        a_val, a_len = a
        b_val, b_len = b
        return ((a_val * pow(10, b_len, mod)) % mod + b_val) % mod, a_len + b_len

