                        can_illuminate = True
                        break

            if not can_illuminate:
                possible = False
                break

        if not possible:
            results.append("NO")
            continue

        # Verify all lanterns can actually get illuminated given their directions
        directions_final = []
        for i in range(n):
            if directions[i] == 'L':
                directions_final.append('L')
            else:
                directions_final.append('R')

        # Check if this configuration actually works
        # Monte Carlo check: this is too slow, so use simpler validation
        # If any lantern has 0 power, it can't illuminate anyone
        # But it still needs to be illuminated

        # Simpler: if all have zero power, impossible
        if all(x == 0 for x in p):
            results.append("NO")
            continue

        # Check edge cases
        if n == 2 and (p[0] == 0 or p[1] == 0):
            results.append("NO")
            continue

        # For larger n, a pattern like RLRL... often works
        alt_pattern = []
        for i in range(n):
            if i % 2 == 0:
                alt_pattern.append('L')
            else:
                alt_pattern.append('R')

        # Verify this pattern
        valid_pattern = True
        for i in range(n):
            can_be_lit = False
            if alt_pattern[i] == 'L' and i > 0:
                # This lantern is sent left, check if it can be lit from right
                for j in range(i+1, min(i + p[i] + 1, n)):
                    if j - p[j] <= i:  # lantern j sends left to i
                        can_be_lit = True
                        break
            elif alt_pattern[i] == 'R' and i < n-1:
                # This lantern is sent right, check if it can be lit from left
                for j in range(max(0, i - p[i]), i):
                    if j + p[j] >= i + 1:  # lantern j sends right to i
                        can_be_lit = True
                        break

            if not can_be_lit:
                if p[i] == 0:
                    # Cannot illuminate anything, might still be lit
                    pass

        # Fallback: use the computed directions but ensure they're valid
        directions = [''] * n
        for i in range(n):
            if i == 0:
                directions[0] = 'R'
            else:
                # Previous lantern illuminated this one from left
                if directions[i-1] == 'R' and i <= directions[i-1] + 1:
                    directions[i] = 'L'
                elif i > 0:
                    directions[i] = 'R'

        # Final validation
        def check_directions(dirs, powers):
            for i in range(len(dirs)):
                lit = False
                if dirs[i] == 'L':
                    # Check if lit from right
                    for j in range(i+1, len(dirs)):
                        if dirs[j] == 'L' and j - powers[j] <= i:
                            lit = True
