                else:
                    # Check if lit from left
                    for j in range(max(0, i - 1), i):
                        if dirs[j] == 'R' and j + powers[j] >= i + 1:
                            lit = True
                            break
                if not lit:
                    return False
            return True

        if check_directions(directions, p):
            results.append(f"YES\n{''.join(directions)}")
        else:
            results.append("NO")

    return '\n'.join(results)

