    l, r = map(int, lines[1].split())

    result = []

    for x1 in range(1, n + 1):
        found = False

        # y1 range: l <= x1*y1 <= r and 1 <= y1 <= m
        min_y1 = max(1, (l + x1 - 1) // x1)  # ceil(l/x1)
        max_y1 = min(m, r // x1)

        if min_y1 > max_y1:
            result.append("-1")
            continue

        for y1 in range(min_y1, max_y1 + 1):
            P = x1 * y1

            # Find x2 in [x1+1, min(n, P)] where x2 divides P
            end_x2 = min(n + 1, P + 1)
            for x2 in range(x1 + 1, end_x2):
                if P % x2 == 0:
                    y2 = P // x2
                    # y2 < y1 is guaranteed since x2 > x1
                    # just need y2 >= 1 (automatic since x2 <= P)
                    result.append(f"{x1} {y1} {x2} {y2}")
                    found = True
                    break

            if found:
                break

        if not found:
            result.append("-1")

    return '\n'.join(result)

