def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""
    n, m = map(int, lines[0].split())
    roads = []
    for i in range(m):
        u, v = map(int, lines[1 + i].split())
        roads.append((min(u, v), max(u, v)))

    def should_conflict(edge1, edge2, n):
        """Check if two edges interlace (would cross if both placed inside)"""
        u1, v1 = edge1
        u2, v2 = edge2
        a, b = u1 - 1, v1 - 1
        c, d = u2 - 1, v2 - 1

        # If any edge has invalid endpoints
        if a == b or c == d:
            return False

        # Check interlacing: vertices should alternate between {a, b} and {c, d}
        # Sorted order around circle should be: a, c, b, d OR a, d, b, c
        return (a < c < b < d) or (c < a < d < b)

    # Build conflict graph: conflict[i][j] = True if roads i and j must be on different sides
    conflict = [[False] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if should_conflict(roads[i], roads[j], n):
                conflict[i][j] = True
                conflict[j][i] = True

    # Try 2-coloring the conflict graph (bipartite check)
    colors = [-1] * m  # -1 = uncolored, 0 = type 1, 1 = type 2
    for i in range(m):
        if colors[i] == -1:
            stack = [(i, 0)]  # (node, assigned_color)
            while stack:
                node, col = stack.pop()
                colors[node] = col
                for neighbor in range(m):
                    if conflict[node][neighbor]:
                        if colors[neighbor] == -1:
                            colors[neighbor] = 1 - col
                            stack.append((neighbor, 1 - col))
                        elif colors[neighbor] == col:
                            # Same color conflict - graph is not bipartite
                            return "Impossible"

    # Determine which side each road goes on (0 = inside, 1 = outside)
    result = []
    for i in range(m):
        if colors[i] == 0:
            result.append('i')
        else:
            result.append('o')

    return ''.join(result)

