class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)
        self.build(arr, 1, 0, self.n - 1)

    def build(self, arr, node, start, end):
        if start == end:
            self.tree[node] = arr[start]
            self.tree_pos[node] = start
            return
        mid = (start + end) // 2
        self.build(arr, 2*node, start, mid)
        self.build(arr, 2*node+1, mid+1, end)
        self.tree[node] = max(self.tree[2*node], self.tree[2*node+1])
        self.tree_pos[node] = self.tree_pos[2*node] if (self.tree[2*node] >= self.tree[2*node+1]) else self.tree_pos[2*node+1]

    def query(self, L, R):
        if L > R:
            return 0, 0
        return self._query(1, 0, self.n - 1, L, R)

    def _query(self, node, start, end, L, R):
        if R < start or end < L:
            return 0
        if L <= start and end <= R:
            return self.tree[node]
        mid = (start + end) // 2
        left_max, left_pos = self._query(2*node, start, mid, L, R)
        right_max, right_pos = self._query(2*node+1, mid+1, end, L, R)

        if left_max > right_max:
            return left_max, left_pos
        else:
            return right_max, right_pos


