        return pH[r] - pH[l - 1]

    def get_blocked_dist(l, r):
        """Sum of blocked distances: d[l-1] through d[r-1+1]"""
        if l > r:
            return 0
        if r == n:  # handle wrap case
            return total_dist - (get_height_sum(l, l-1) if l > 1 else 0)
        return total_dist - (get_height_sum(l-1, r) if r > 0 else 0)

