            blocked_height = get_height_sum(ai, bi)

        # Segment tree query for [1, ai-1]
        left_max, _ = st.query(0, left_end - 1 if left_end > 0 else -1)

        # Segment tree query for [bi+1, n]
        right_max, _ = st.query(right_start - 1 if right_start > 0 else -1, n - 1)

        if left_max == 0 and right_max == 0:
            # All trees blocked (shouldn't happen per problem)
            results.append(0)
