                        energy = 2 * (get_height_sum(j, j) + get_height_sum(k, k)) + dist
                        results.append(max(results[-1] if results else [0], energy))

        # Simplified: just use max available
        max_h = max(left_max, right_max)
        dist = total_dist - blocked_dist if left_end > 0 and right_start > 0 else total_dist

        ans = 2 * left_max + dist
        if right_max > 0:
