    def get_kernel(x):
        """Get square-free kernel of x"""
        result = 1
        d = 2
        while d * d <= x:
            if x % d == 0:
                count = 0
                while x % d == 0:
                    count += 1
                    x //= d
                if count % 2 == 1:
                    result *= d
            d += 1
        if x > 1:
            result *= x
        return result

