    kernel_counts = {}
    for x in a:
        k = get_kernel(x)
        kernel_counts[k] = kernel_counts.get(k, 0) + 1

    group_sizes = sorted(kernel_counts.values(), reverse=True)

    # Base case
    if n <= 1:
        return str(1)

    # Precompute factorials
    factorial = [1] * (n + 1)
    for i in range(1, n + 1):
        factorial[i] = factorial[i - 1] * i % MOD

    inv_factorial = [1] * (n + 1)
    inv_factorial[n] = pow(factorial[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv_factorial[i] = inv_factorial[i + 1] * (i + 1) % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return factorial[n] * inv_factorial[k] % MOD * inv_factorial[n - k] % MOD

    # DP approach: For each kernel group, count arrangements where no two
    # elements from the same group are adjacent
    # dp[last_group_idx] = number of valid placements

    dp = [0] * (len(group_sizes) + 2)  # extended for None case
    dp[0] = 1  # Starting with no group processed

    total = sum(group_sizes)
    positions_left = total

    for idx, gsize in enumerate(group_sizes):
        if gsize == 1:
            # Single element from this kernel
            dp[idx + 1] = dp[idx]
            positions_left -= 1
        else:
            # Multiple elements from same kernel - need to insert in gaps
            # between previously placed elements
            ways = 0
            for prev in range(len(group_sizes)):
                if prev == idx:
                    continue
                if dp[prev] == 0:
                    continue

                # If prev is actual group index or 0 (no group yet)
                if dp[prev]:
                    # Count ways to insert this group's elements
                    if idx == 0:
                        # First group
                        ways = 1
                    else:
                        # Insert gsize elements among correctly placed elements
                        # i.g., 1 element has 1 slot, 2 consecutive have gsize-1+1 slots
                        ways = sum((gsize + i) for i in range(gsize))
                    ways = ways % MOD
                    dp[idx + 1] = ways

    # Use inclusion-exclusion
    ans = 0
    for mask in range(1 << len(group_sizes)):
        count = bin(mask).count('1')
        ways = factorial[total]

        if count & 1:
            ans = (ans - ways) % MOD
        else:
            ans = (ans + ways) % MOD

    ans = (ans + MOD) % MOD
    return str(ans)

