    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Position map for quick lookup
    pos = {x: i for i, x in enumerate(p)}

    # Union-Find data structure
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
        return

    # Build connected components based on constraints
    # For each number, if a-x or b-x exists, they must be in the same set
    for i, x in enumerate(p):
        # If x in A, then a-x must be in A
        y = a - x
        if y in pos and pos[y] != i:
            union(i, pos[y])

        # If x in B, then b-x must be in B
        y = b - x
        if y in pos and pos[y] != i:
            union(i, pos[y])

    # Group indices by component root
    root_to_indices = {}
    for i in range(n):
        r = find(i)
        if r not in root_to_indices:
            root_to_indices[r] = []
        root_to_indices[r].append(i)

    # For each component, check if it can satisfy A and/or B constraints
    # A component can be in A only if for all x in component, (a-x) exists in pos
    # A component can be in B only if for all x in component, (b-x) exists in pos
    can_be_a = {}
    can_be_b = {}

    for r in root_to_indices:
        indices = root_to_indices[r]
        can_be_a[r] = True
        can_be_b[r] = True

        # Check A constraint for all elements in this component
        for i in indices:
            x = p[i]
            y_a = a - x
            if y_a not in pos:
                can_be_a[r] = False
                break

        # Check B constraint for all elements in this component
        if can_be_b[r]:
            for i in indices:
                x = p[i]
                y_b = b - x
                if y_b not in pos:
                    can_be_b[r] = False
                    break

    # Check if at least one valid assignment exists
    if not any(can_be_a.get(r) or can_be_b.get(r) for r in root_to_indices):
        return "NO\n"

    # Assign each component to a set
    assignment = [0] * n
    for r in root_to_indices:
        if not can_be_b[r]:
            # Must be in A (0)
            for i in range(n):
                if find(i) == r:
                    assignment[i] = 0
        else:
            # Can be in A or B, default to A (0)
            for i in range(n):
                if find(i) == r:
                    assignment[i] = 0

    return "YES\n" + " ".join(map(str, assignment)) + "\n"

