MOD = 10**9 + 7

def S(n):
    """Sort digits of n in ascending order and return the result"""
    s = str(n)
    digits = sorted(s)
    return int(''.join(digits))

def solution(input_str):
    """Compute sum of S(i) for i from 1 to X, modulo 10^9 + 7"""
    s = input_str.strip()
    limit = int(s)

    result = 0
    for i in range(1, limit + 1):
        result = (result + S(i)) % MOD

    return str(result)
